import json,sys
d=json.load(open(sys.argv[1])); cat=json.load(open(sys.argv[2]))
q={x['id']:x for x in d['qa_log']}
items=cat['items']
blk=[i for i in items if i.get('missing_effect')=='block']
print(len(items),len(blk))
by={}
for x in d['qa_log']:
    for it in x.get('required_info_items',[]): by.setdefault(it,[]).append(x['id'])
for dom in cat['in_scope_domains']:
    cd=d['matrix'].get(dom)
    if not cd: print('no matrix',dom); continue
    c=cd['web']; refs=set([c['qa_ref']]+c.get('qa_refs',[]))
    for i in items:
        if i['domain']!=dom: continue
        got=set(by.get(i['item_id'],[]))
        print(dom,i['item_id'],i['missing_effect'],i['required_when'],'grounded_in_cell' if got&refs else ('ANSWERED_ELSEWHERE' if got else 'UNANSWERED'),sorted(got&refs) or sorted(got))
E

